"""Pydantic v2 schemas defining the typed contracts for MedAgent."""

from typing import Dict, List, Literal, Optional
from pydantic import BaseModel, ConfigDict, Field

CLINICAL_DISCLAIMER: str = (
    "Decision-support draft generated by AI agents. It is not a diagnosis "
    "and must be reviewed, corrected and approved by a licensed physician "
    "before any clinical use."
)


class CaseInput(BaseModel):
    """Initial multimodal input received for clinical case evaluation."""
    model_config = ConfigDict(extra="forbid")

    case_id: str
    clinical_text: str = Field(description="Free-text clinical notes, history, or examination findings")
    patient_age: Optional[int] = Field(default=None, ge=0, le=130)
    patient_sex: Optional[Literal["male", "female", "other"]] = None
    image_paths: List[str] = Field(default_factory=list)
    lab_paths: List[str] = Field(default_factory=list)
    lab_text: Optional[str] = Field(default="")


class ImagingFinding(BaseModel):
    """Individual pathology finding detected on chest radiograph."""
    model_config = ConfigDict(extra="forbid")

    finding: str
    probability: float = Field(ge=0.0, le=1.0)
    location: str
    severity: Literal["low", "moderate", "high"] = Field(
        description="Heuristic indicative severity based on probability and extent"
    )
    confidence: Literal["low", "moderate", "high"]


class ImagingReport(BaseModel):
    """Structured report returned by the Imaging Agent."""
    model_config = ConfigDict(extra="forbid")

    status: Literal["ok", "unavailable", "skipped", "error"]
    modality: str = "chest X-ray"
    model_name: str = "TorchXRayVision-DenseNet121"
    findings: List[ImagingFinding] = Field(default_factory=list)
    heatmap_paths: Dict[str, str] = Field(
        default_factory=dict,
        description="Mapping of pathology name to generated Grad-CAM heatmap PNG path"
    )
    image_quality_notes: List[str] = Field(default_factory=list)
    message: str = ""


class LabResult(BaseModel):
    """Normalized individual laboratory test result."""
    model_config = ConfigDict(extra="forbid")

    test: str
    raw_name: str
    value: float
    unit: str
    ref_low: Optional[float] = None
    ref_high: Optional[float] = None
    flag: Literal["critical low", "low", "normal", "high", "critical high", "unknown"]


class LabPattern(BaseModel):
    """Clinical pattern synthesized across multiple lab results."""
    model_config = ConfigDict(extra="forbid")

    name: str
    description: str
    supporting_tests: List[str] = Field(default_factory=list)
    urgency: Literal["routine", "soon", "urgent"]


class LabReport(BaseModel):
    """Structured report returned by the Lab Agent."""
    model_config = ConfigDict(extra="forbid")

    status: Literal["ok", "unavailable", "skipped", "error"]
    results: List[LabResult] = Field(default_factory=list)
    patterns: List[LabPattern] = Field(default_factory=list)
    unparsed_lines: List[str] = Field(default_factory=list)
    message: str = ""


class Evidence(BaseModel):
    """Passage retrieved from the medical knowledge base."""
    model_config = ConfigDict(extra="forbid")

    id: str = Field(description="Citation identifier, e.g. S1, S2")
    source: str
    section: str
    passage: str
    score: float
    query: str


class RagReport(BaseModel):
    """Structured report returned by the RAG Agent."""
    model_config = ConfigDict(extra="forbid")

    status: Literal["ok", "empty", "error", "skipped"]
    queries: List[str] = Field(default_factory=list)
    evidence: List[Evidence] = Field(default_factory=list)
    backend: str = "numpy"
    message: str = ""


class Differential(BaseModel):
    """Ranked differential diagnosis item with cited justification."""
    model_config = ConfigDict(extra="forbid")

    condition: str
    likelihood: Literal["high", "moderate", "low"]
    rationale: str
    supporting_findings: List[str] = Field(default_factory=list)
    evidence_ids: List[str] = Field(
        default_factory=list,
        description="List of cited evidence IDs matching Evidence.id (e.g. ['S1', 'S2'])"
    )
    against: Optional[str] = Field(default="", description="Findings that argue against or are discordant")


class ClinicalDraft(BaseModel):
    """Draft synthesis produced by Clinical Reasoning Agent."""
    model_config = ConfigDict(extra="forbid")

    summary: str
    differentials: List[Differential] = Field(default_factory=list)
    suggested_workup: List[str] = Field(default_factory=list)
    red_flags: List[str] = Field(default_factory=list)
    uncertainties: List[str] = Field(default_factory=list)
    mode: Literal["llm", "rule_engine"] = "rule_engine"


class SafetyIssue(BaseModel):
    """Individual safety check finding or violation."""
    model_config = ConfigDict(extra="forbid")

    severity: Literal["info", "warning", "blocker"]
    code: str
    message: str
    where: str


class SafetyReport(BaseModel):
    """Structured report returned by Safety Agent."""
    model_config = ConfigDict(extra="forbid")

    verdict: Literal["pass", "pass_with_warnings", "blocked"]
    issues: List[SafetyIssue] = Field(default_factory=list)
    urgent: bool = False
    urgent_reasons: List[str] = Field(default_factory=list)
    revised: Optional[str] = None


class DoctorDecision(BaseModel):
    """Physician decision submitted at the human-in-the-loop gate."""
    model_config = ConfigDict(extra="forbid")

    decision: Literal["approve", "reject", "edit"]
    reviewer: str
    notes: Optional[str] = ""
    edited_summary: Optional[str] = None


class FinalReport(BaseModel):
    """Released clinical decision-support report."""
    model_config = ConfigDict(extra="forbid")

    case_id: str
    released: bool
    reviewer: str
    decision: Literal["approve", "reject", "edit"]
    markdown: str
    pdf_path: Optional[str] = None
